(9,27,28,'Shock','A life-threatening condition in which circulation is inadequate to supply oxygen to body tissues.',false,true),
(9,27,29,'Fracture','A break in a bone — requires immobilization and medical evaluation.',false,true),
(9,27,30,'P.R.I.C.E.','Protect, Rest, Ice, Compress, Elevate — the treatment protocol for sprains and strains.',false,true),
(9,27,31,'Emergency survival kit','A collection of supplies needed to sustain a household for 72+ hours during or after an emergency.',false,true),
(9,27,32,'Heimlich maneuver','An abdominal thrust technique used to dislodge a foreign object from a choking person''s airway.',false,true),
(9,27,33,'Anaphylaxis','A severe, potentially fatal allergic reaction requiring immediate epinephrine treatment.',false,true),
(9,27,34,'Triage','The process of sorting injured people by severity to prioritize treatment.',false,true),
(9,27,35,'Tourniquet','A tight band applied to a limb to stop severe bleeding when direct pressure fails.',false,true),
(9,27,36,'Hypothermia','Dangerously low body temperature caused by exposure to cold; requires gradual rewarming.',false,true),
(9,27,37,'Recovery position','A side-lying position used for unconscious breathing persons to keep the airway open.',false,true),
(9,27,38,'Check-Call-Care','The first aid sequence: check the scene for safety, call 911 for serious emergencies, then care for the person.',false,true),
(9,27,39,'Epinephrine auto-injector','A device, such as an EpiPen, that delivers medicine to treat a severe allergic reaction.',false,true),
(9,28,40,'Health care system','All the medical care available to a nation''s people, the way they receive care, and the way they pay for it.',false,true),
(9,28,41,'Primary care physician','A medical doctor who provides physical checkups and general care.',false,true),
(9,28,42,'Public health','A community''s effort to protect the health of all its people.',false,true),
(9,28,43,'Health insurance','Private and government programs that pay for part or all of a person''s medical costs.',false,true),
(9,28,44,'Air pollution','Contamination of the atmosphere by harmful substances including gases and particulate matter.',false,true),
(9,28,45,'Smog','A form of air pollution created when sunlight reacts with vehicle and industrial emissions.',false,true),
(9,28,46,'Radon','A colorless, odorless radioactive gas from soil — the second leading cause of lung cancer in the U.S.',false,true),
