(9,28,55,'Environmental health','The field studying how the natural and built environment affects human health.',false,true),
(9,28,56,'Air quality index','A measure of how clean or polluted outdoor air is and what health effects may be of concern.',false,true),
(9,28,57,'Greenhouse gases','Gases (CO₂, methane) that trap heat in the atmosphere, contributing to climate change.',false,true),
